            // ==================== BUILDER TESTS ====================
            console.log("\n--- Running Builder Tests ---");

            function testBuilder(builderName, expectedMethods) {
                window.__TEST_RESULTS__.total++;
                try {
                    const builderClass = Filament[builderName];
                    if (typeof builderClass !== "function") {
                        throw new Error(`Builder ${builderName} is not a constructor on Filament namespace`);
                    }

                    // Verify instantiation
                    let instance;
                    if (builderName === "InstanceBuffer$Builder" || builderName === "RenderableManager$Builder") {
                        instance = new builderClass(1);
                    } else if (builderName === "LightManager$Builder") {
                        instance = new builderClass(Filament.LightManager$Type.DIRECTIONAL);
                    } else {
                        instance = new builderClass();
                    }

                    if (!instance || typeof instance !== "object") {
                        throw new Error(`Failed to instantiate ${builderName}`);
                    }

                    // Verify prototype / instance methods
                    let verifiedCount = 0;
                    for (const method of expectedMethods) {
                        if (typeof builderClass.prototype[method] === "function" || typeof instance[method] === "function") {
                            verifiedCount++;
                        }
                    }
                    if (verifiedCount === 0 && expectedMethods.length > 0) {
                        throw new Error(`Builder ${builderName} has none of expected methods`);
                    }

                    // Verify chaining invariant on safe methods
                    if (builderName === "Texture$Builder" && typeof instance.width === "function") {
                        const chained = instance.width(64);
                        if (!chained || typeof chained !== "object") {
                            throw new Error(`Texture$Builder.width() did not return a builder object`);
                        }
                    } else if (builderName === "BufferObject$Builder" && typeof instance.size === "function") {
                        const chained = instance.size(1024);
                        if (!chained || typeof chained !== "object") {
                            throw new Error(`BufferObject$Builder.size() did not return a builder object`);
                        }
                    }

                    if (typeof instance.delete === "function") {
                        instance.delete();
                    }

                    window.__TEST_RESULTS__.passed++;
                    console.log(`[PASS] Builder ${builderName} (${verifiedCount}/${expectedMethods.length} methods verified)`);
                } catch (err) {
                    window.__TEST_RESULTS__.failed++;
                    const msg = err && err.message ? err.message : String(err);
                    window.__TEST_RESULTS__.errors.push({ className: builderName, methodName: "builder", error: msg });
                    console.error(`[FAIL] Builder ${builderName}: ${msg}`);
                }
            }
