            console.log("\n--- Running Setter Tests ---");

            const SETTER_STRATEGIES = {
                boolean: {
                    makeValue: (before) => !before,
                    matches: (after, expected) => after === expected,
                },
                number: {
                    makeValue: (before, { setterName }) => {
                        const overrides = {
                            setSampleCount: before === 4 ? 2 : 4,
                            setAnisotropy: before === 1 ? 2 : 1,
                            setAperture: before === 16 ? 8 : 16,
                            setFocusDistance: 1.5,
                            setSensitivity: 200,
                            setShutterSpeed: 0.016,
                        };
                        return overrides[setterName] ?? (before === 0 ? 1 : before + 1);
                    },
                    matches: (after, expected) => Math.abs(after - expected) < 1e-3,
                },
                string: {
                    makeValue: () => "test_val_" + Math.floor(Math.random() * 1000),
                    matches: (after, expected) => after === expected,
                },
                enum: {
                    makeValue: (before, { enumName }) => {
                        const enumObj = Filament[enumName];
                        if (!enumObj) throw new Error(`Enum ${enumName} not found on Filament`);
                        for (const key of Object.keys(enumObj)) {
                            if (key === "values") continue;
                            const candidate = enumObj[key];
                            if (candidate && (before === undefined || candidate.value !== before.value)) {
                                return candidate;
                            }
                        }
                        return before;
                    },
                    matches: (after, expected) => (after && expected && after.value === expected.value) ||
                                                  (formatValue(after) === formatValue(expected)),
                },
                vector: {
                    makeValue: (before, { vectorLen }) => {
                        const len = vectorLen || (Array.isArray(before) ? before.length : 2);
                        return Array.from({ length: len }, (_, i) => i + 2);
                    },
                    matches: (after, expected) => Array.isArray(after) && after[0] === expected[0],
                    restoreValue: (before, { vectorLen }) => {
                        const len = vectorLen || 2;
                        return Array.isArray(before) ? before.slice(0, len) : [1, 1];
                    },
                },
                viewport: {
                    makeValue: () => [10, 20, 640, 480],
                    matches: (after) => Array.isArray(after) &&
                        after[0] === 10 && after[1] === 20 && after[2] === 640 && after[3] === 480,
                    restoreValue: (before) => (before && before[2] > 0 && before[3] > 0) ? before : [0, 0, 640, 480],
                },
                object: {
                    makeValue: (before) => {
                        const val = Object.assign({}, before);
                        if ("minScale" in val && "maxScale" in val) val.minScale = val.maxScale;
                        if ("enabled" in val) val.enabled = !before.enabled;
                        else if ("clear" in val) val.clear = !before.clear;
                        return val;
                    },
                    matches: (after, expected) => {
                        if ("enabled" in expected) return after && after.enabled === expected.enabled;
                        if ("clear" in expected) return after && after.clear === expected.clear;
                        return typeof after === "object" && after !== null;
                    },
                },
                camera: { makeValue: () => camera, matches: (after) => after !== null },
                scene: { makeValue: () => scene, matches: (after) => after !== null },
                colorGrading: { makeValue: () => colorGrading, matches: (after) => after !== null },
            };

            function testSetter(className, fixture, setterName, getterName, paramType, enumName, vectorLen) {
                window.__TEST_RESULTS__.total++;
                try {
                    if (!fixture) throw new Error(`Fixture for ${className} is null or undefined`);
                    if (typeof fixture[setterName] !== "function") throw new Error(`Setter ${setterName} is not a function`);
                    if (typeof fixture[getterName] !== "function") throw new Error(`Getter ${getterName} is not a function`);

                    const strategy = SETTER_STRATEGIES[paramType];
                    if (!strategy) throw new Error(`Unsupported setter strategy for param type: ${paramType}`);

                    const ctx = { setterName, getterName, enumName, vectorLen };
                    const before = fixture[getterName]();
                    const testVal = strategy.makeValue(before, ctx);

                    fixture[setterName](testVal);
                    const after = fixture[getterName]();

                    if (!strategy.matches(after, testVal, before)) {
                        throw new Error(`Expected ${getterName}() to reflect ${formatValue(testVal)}, got ${formatValue(after)}`);
                    }

                    const restoreVal = strategy.restoreValue ? strategy.restoreValue(before, ctx) : before;
                    fixture[setterName](restoreVal);

                    window.__TEST_RESULTS__.passed++;
                    console.log(`[PASS] ${className}.${setterName}(${formatValue(testVal)}) -> ${getterName}() verified`);
                } catch (err) {
                    window.__TEST_RESULTS__.failed++;
                    const msg = err && err.message ? err.message : String(err);
                    window.__TEST_RESULTS__.errors.push({ className, methodName: setterName, error: msg });
                    console.error(`[FAIL] ${className}.${setterName}(): ${msg}`);
                }
            }
            // Camera Setters (3 methods)
